public class UPSVendPriceAdmAdjustment extends RunBase
{
    #DEFINE.CurrentVersion(1)

    #LOCALMACRO.CurrentList
        priceBase,
        priceChg,
        priceAmount
    #ENDMACRO

    QueryRun        queryRun;

    DialogField     fieldPriceBase;
    DialogField     fieldPriceChg;
    DialogField     fieldPriceAmount;

    UPSPriceBase    priceBase;
    Percent         priceChg;
    Amount          priceAmount;

}

Method.Source:
public Object dialog()
{
    DialogRunbase   dialog = super();
    DialogGroup     dialogPriceGroup;

    dialogPriceGroup    = dialog.addGroup("@SYS23842");

    dialogPriceGroup.columns(3);

    fieldPriceBase      = dialog.addField(enumstr(UPSPriceBase), "@SYS11865", "@SYS138545");
    fieldPriceChg       = dialog.addField(extendedtypestr(Percent)  , "@SYS62861", "@SYS138545");
    fieldPriceAmount    = dialog.addField(extendedtypestr(Amount)   , "@SYS62867", "@SYS138545");

    dialog.addMenuItemButton(MenuItemType::Display, menuitemdisplaystr(RunBaseQueryDialog), DialogMenuItemGroup::BottomGrp);

    return dialog;
}

boolean  getFromDialog()
{
    priceBase   = fieldPriceBase.value();
    priceChg    = fieldPriceChg.value();
    priceAmount = fieldPriceAmount.value();

    return true;
}

void new()
{
    super();

    queryRun = new QueryRun(querystr(UPSVendPriceAdmTrans));
}

void run()
{
    UPSVendPriceAdmTrans  vendPriceAdmTrans;

    ttsbegin;

    while (queryRun.next())
    {
        vendPriceAdmTrans = queryRun.get(tableNum(UPSVendPriceAdmTrans));

        this.updateNow(vendPriceAdmTrans);
    }

    ttscommit;
}

public boolean  unpack(container  _packedClass)
{
    Integer     version = RunBase::getVersion(_packedClass);
    container   packedQueryRun;

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList, packedQueryRun] = _packedClass;

            if (SysQuery::isPackedOk(packedQueryRun))
                queryRun   = new QueryRun(packedQueryRun);
            else
                return false;
            break;
        default :
            return false;
    }

    return true;
}

final protected void updateVendPriceAmount(UPSVendPriceAdmTrans _vendPriceAdmTrans)
{
    switch (priceBase)
    {
        case UPSPriceBase::Blank:
            break;
        case UPSPriceBase::Zero:
            _vendPriceAdmTrans.Amount = priceAmount;
            break;
        case UPSPriceBase::Current:
            _vendPriceAdmTrans.Amount += _vendPriceAdmTrans.Amount * (priceChg / 100) + priceAmount;
            break;
        default:
            EventHandlerResult result = EventHandlerResult::newSingleResponse();

            this.retrievePurchPriceAmountDelegate(this, _vendPriceAdmTrans, result);

            if (result.hasResult())
            {
                _vendPriceAdmTrans.Amount = result.result();
            }
            break;
    }
}

void  updateQueryBuild(UPSVendPriceAdmTrans _vendPriceAdmTrans)
{
    QueryBuildRange queryBuildRange;

    queryBuildRange = queryRun.query().dataSourceTable(tablenum(UPSVendPriceAdmTrans)).findRange(fieldnum(UPSVendPriceAdmTrans, JournalNum));
    queryBuildRange.value(queryValue(_vendPriceAdmTrans.JournalNum));
    queryBuildRange.status(RangeStatus::Hidden);

    queryRun.title(UPSVendPriceAdmAdjustment::description());
}

static void main(Args args)
{
    UPSVendPriceAdmTrans        vendPriceAdmTrans;
    UPSVendPriceAdmAdjustment   vendPriceAdmAdjustment = new UPSVendPriceAdmAdjustment();
    FormDataSource              formDS;

    if (! args.dataset() == tablenum(UPSVendPriceAdmTrans))
    {
        throw error("@SYS18626");
    }

    vendPriceAdmTrans = args.record();

    if (! vendPriceAdmTrans.JournalNum)
    {
        throw error("@SYS59036");
    }

    vendPriceAdmAdjustment.getLast();
    vendPriceAdmAdjustment.updateQueryBuild(vendPriceAdmTrans);

    if (vendPriceAdmAdjustment.prompt())
    {
        vendPriceAdmAdjustment.runOperation();

        if (args.record().isFormDataSource())
        {
            formDS = args.record().dataSource();
            formDS.research(true);
        }
    }
}
